.searchoptions select {
	flex: 1;
	padding: 12px;
	background: rgba(255, 255, 255, 0.08);
	border: 1px solid rgba(255, 255, 255, 0.2);
	borderradius: 8px;
	color: ffffff;
	fontsize: 14px;
	fontfamily: inherit;
}

.searchoptions select:focus {
	outline: none;
	bordercolor: rgba(255, 255, 255, 0.4);
}

.searchoptions select option {
	background: 1a1a1a;
	color: ffffff;
}

.advancedoptions {
	display: flex;
	gap: 20px;
	marginbottom: 16px;
	flexwrap: wrap;
}

.checkboxlabel {
	display: flex;
	alignitems: center;
	gap: 8px;
	color: rgba(255, 255, 255, 0.8);
	fontsize: 14px;
	cursor: pointer;
}

.checkboxlabel input[type="checkbox"] {
	width: auto;
	margin: 0;
	accentcolor: rgba(255, 255, 255, 0.8);
}

input, textarea {
	width: 100%;
	padding: 16px;
	background: rgba(255, 255, 255, 0.08);
	border: 1px solid rgba(255, 255, 255, 0.2);
	borderradius: 8px;
	color: ffffff;
	fontsize: 16px;
	fontfamily: inherit;
	marginbottom: 16px;
	transition: all 0.2s ease;
}

input:focus, textarea:focus {
	outline: none;
	bordercolor: rgba(255, 255, 255, 0.4);
	background: rgba(255, 255, 255, 0.12);
}

::placeholder {
	color: rgba(255, 255, 255, 0.5);
}

button {
	width: 100%;
	padding: 16px;
	background: rgba(255, 255, 255, 0.1);
	border: 1px solid rgba(255, 255, 255, 0.2);
	borderradius: 8px;
	color: ffffff;
	cursor: pointer;
	transition: all 0.2s ease;
	fontweight: 500;
	fontsize: 16px;
	fontfamily: inherit;
	marginbottom: 15px;
}

button:hover {
	background: rgba(255, 255, 255, 0.15);
	bordercolor: rgba(255, 255, 255, 0.3);
	transform: translateY(1px);
}

button:active {
	transform: translateY(0);
}

button:disabled {
	opacity: 0.5;
	cursor: notallowed;
	transform: none;
}

.resultscontainer {
	margintop: 30px;
}

.resultitem {
	background: rgba(255, 255, 255, 0.08);
	border: 1px solid rgba(255, 255, 255, 0.1);
	borderradius: 12px;
	padding: 24px;
	marginbottom: 16px;
	transition: all 0.2s ease;
}

.resultitem:hover {
	background: rgba(255, 255, 255, 0.12);
	bordercolor: rgba(255, 255, 255, 0.2);
	transform: translateY(2px);
}

.resulttitle {
	marginbottom: 10px;
}

.resulttitle a {
	color: ffffff;
	textdecoration: none;
	fontsize: 1.1rem;
	fontweight: 500;
	transition: color 0.2s ease;
}

.resulttitle a:hover {
	color: rgba(255, 255, 255, 0.8);
	textdecoration: underline;
}

.resulturl {
	color: rgba(255, 255, 255, 0.6);
	fontsize: 0.9rem;
	fontweight: 400;
}

.resultsummary {
	margin: 12px 0;
	color: rgba(255, 255, 255, 0.8);
	fontsize: 0.95rem;
	lineheight: 1.5;
}

.resultcontent {
	margin: 12px 0;
	color: rgba(255, 255, 255, 0.7);
	fontsize: 0.9rem;
	lineheight: 1.6;
	background: rgba(255, 255, 255, 0.05);
	padding: 12px;
	borderradius: 6px;
	borderleft: 3px solid rgba(255, 255, 255, 0.2);
}

.resulthighlights {
	margin: 12px 0;
}

.resulthighlights h4 {
	color: rgba(255, 255, 255, 0.9);
	fontsize: 0.9rem;
	marginbottom: 8px;
}

.highlightitem {
	background: rgba(255, 255, 255, 0.05);
	borderleft: 3px solid rgba(255, 255, 255, 0.3);
	padding: 8px 12px;
	margin: 6px 0;
	borderradius: 4px;
	fontsize: 0.9rem;
	color: rgba(255, 255, 255, 0.8);
	fontstyle: italic;
}

.resultactions {
	margintop: 15px;
	display: flex;
	gap: 10px;
}

.actionbtn {
	padding: 6px 12px;
	background: rgba(255, 255, 255, 0.1);
	border: 1px solid rgba(255, 255, 255, 0.2);
	borderradius: 6px;
	color: rgba(255, 255, 255, 0.9);
	fontsize: 0.8rem;
	cursor: pointer;
	transition: all 0.2s ease;
	width: auto;
	margin: 0;
}

.actionbtn:hover {
	background: rgba(255, 255, 255, 0.15);
	transform: none;
}

.generatedimage {
	textalign: center;
	margintop: 20px;
}

.generatedimage img {
	maxwidth: 100%;
	height: auto;
	borderradius: 12px;
	border: 1px solid rgba(255, 255, 255, 0.2);
}

.generatedimage p {
	margintop: 15px;
	color: rgba(255, 255, 255, 0.7);
	fontstyle: italic;
	fontweight: 400;
}

.imageoptions {
	display: grid;
	gridtemplatecolumns: repeat(autofit, minmax(250px, 1fr));
	gap: 16px;
	marginbottom: 20px;
	padding: 20px;
	background: rgba(255, 255, 255, 0.05);
	borderradius: 12px;
	border: 1px solid rgba(255, 255, 255, 0.1);
}

.optiongroup {
	display: flex;
	flexdirection: column;
	gap: 6px;
}

.optiongroup label {
	color: rgba(255, 255, 255, 0.8);
	fontsize: 14px;
	fontweight: 500;
}

.optiongroup select,
.optiongroup input[type="number"] {
	marginbottom: 0;
	padding: 8px 12px;
	fontsize: 14px;
}

.checkboxgroup {
	flexdirection: row;
	alignitems: center;
	gap: 8px;
}

.checkboxgroup label {
	margin: 0;
	flexdirection: row;
	alignitems: center;
}

.loginbtn {
	margintop: 15px;
	background: rgba(0, 120, 212, 0.8);
	bordercolor: rgba(0, 120, 212, 0.9);
}

.loginbtn:hover {
	background: rgba(0, 120, 212, 1);
	bordercolor: rgba(0, 120, 212, 1);
}

textarea {
	minheight: 120px;
	resize: vertical;
}

/ Scrollbar styling /
::webkitscrollbar {
	width: 8px;
}

::webkitscrollbartrack {
	background: rgba(255, 255, 255, 0.1);
	borderradius: 4px;
}

::webkitscrollbarthumb {
	background: rgba(255, 255, 255, 0.3);
	borderradius: 4px;
}

::webkitscrollbarthumb:hover {
	background: rgba(255, 255, 255, 0.5);
}

/ Responsive design /
@media (maxwidth: 768px) {
	.container {
		padding: 16px;
	}

	.hero {
		padding: 24px;
		marginbottom: 24px;
	}

	.maincard {
		padding: 24px;
	}

	.hero h1 {
		fontsize: 2rem;
