html:
<!DOCTYPE html>
<html lang="hu">
<head>
  <meta charset="UTF8">
  <meta name="viewport" content="width=devicewidth, initialscale=1.0">
  <title>Kollár Sándor  Intelligens Keresés és Képgenerálás</title>
  <link rel="stylesheet" href="style.css">
  <script authed="location.reload()" src=""></script>
</head>
<body>
  <div class="container">
    <div class="hero">
      <h1 class="textmh1 lg:texth1">Kollár Sándor</h1>
      <p class="textb1">Intelligens keresés és képgenerálás</p>
    </div>

    <div class="maincard">
      <! Authentication section >
      <div id="authsection" class="authsection">
        <div id="loginarea" class="loginarea" style="display: none;">
          <h3 class="textmh4">Bejelentkezés szükséges</h3>
          <p class="textb2">A funkciók használatához jelentkezz be Replit fiókodddal.</p>
          <button onclick="LoginWithReplit()" class="loginbtn textbutton">Bejelentkezés Replittel</button>
        </div>
        <div id="userinfo" class="userinfo" style="display: none;">
          <div class="userprofile">
            <img id="useravatar" src="" alt="Profile" class="useravatar">
            <div class="userdetails">
              <h3 id="username" class="textmh4"></h3>
              <p id="userbio" class="textb2"></p>
            </div>
          </div>
        </div>
      </div>

      <! Tab Navigation >
      <div class="tabnavigation">
        <button id="searchtab" class="tabbutton active textbutton">Keresés</button>
        <button id="imagetab" class="tabbutton textbutton">Képgenerálás</button>
      </div>

      <! Search Content >
      <div id="searchcontent" class="tabcontent active">
        <div class="searchbox">
          <input type="text" id="searchinput" placeholder="Keresés..." class="textbutton">
          <div class="searchoptions">
            <select id="searchtype" class="textbutton">
              <option value="auto">Automatikus</option>
              <option value="neural">Neurális keresés</option>
              <option value="keyword">Kulcsszó keresés</option>
            </select>
            <select id="searchcategory" class="textbutton">
              <option value="">Minden kategória</option>
              <option value="news">Hírek</option>
              <option value="research">Kutatás</option>
              <option value="company">Vállalati</option>
              <option value="github">GitHub</option>
              <option value="linkedin">LinkedIn</option>
              <option value="twitter">Twitter/X</option>
            </select>
          </div>
          <div class="advancedoptions">
            <label class="checkboxlabel">
              <input type="checkbox" id="includehighlights"> Kiemelések
            </label>
            <label class="checkboxlabel">
              <input type="checkbox" id="includesummary"> Összefoglalók
            </label>
            <label class="checkboxlabel">
              <input type="checkbox" id="includecontent"> Teljes tartalom
            </label>
          </div>
          <button id="searchbutton" class="textbutton">Keresés</button>
        </div>
        <div id="searchresults" class="resultscontainer"></div>
      </div>

      <! Image Generation Content >
      <div id="imagecontent" class="tabcontent">
        <div class="imagegenerationbox">
          <textarea id="imageprompt" placeholder="Írj le, milyen képet szeretnél generálni..." rows="3" class="textbutton"></textarea>

          <div class="imageoptions">
            <div class="optiongroup">
              <label for="aspectratio" class="textbutton">Képarány:</label>
              <select id="aspectratio" class="textbutton">
                <option value="1:1">1:1 (Négyzet)</option>
                <option value="16:9" selected>16:9 (Szélesvásznú)</option>
                <option value="21:9">21:9 (Ultraszéles)</option>
                <option value="3:2">3:2 (Fotó)</option>
                <option value="2:3">2:3 (Portré)</option>
                <option value="4:5">4:5 (Instagram)</option>
                <option value="5:4">5:4 (Tájkép)</option>
                <option value="3:4">3:4 (Portré klasszikus)</option>
                <option value="4:3">4:3 (Klasszikus)</option>
                <option value="9:16">9:16 (Mobil portré)</option>
                <option value="9:21">9:21 (Ultra portré)</option>
              </select>
            </div>

            <div class="optiongroup">
              <label for="outputformat" class="textbutton">Formátum:</label>
              <select id="outputformat" class="textbutton">
                <option value="webp">WebP (optimalizált)</option>
                <option value="jpg" selected>JPG (kompatibilis)</option>
                <option value="png">PNG (veszteségmentes)</option>
              </select>
            </div>

            <div class="optiongroup">
              <label for="outputquality" class="textbutton">Minőség:</label>
              <select id="outputquality" class="textbutton">
                <option value="80">80 (gyors)</option>
                <option value="90" selected>90 (kiváló)</option>
                <option value="95">95 (prémium)</option>
                <option value="100">100 (maximum)</option>
              </select>
            </div>

            <div class="optiongroup">
              <label for="safetytolerance" class="textbutton">Biztonság:</label>
              <select id="safetytolerance" class="textbutton">
                <option value="1">1 (szigorú)</option>
                <option value="2" selected>2 (normál)</option>
                <option value="3">3 (engedékeny)</option>
                <option value="4">4 (minimális)</option>
                <option value="5">5 (kikapcsolva)</option>
              </select>
            </div>

            <div class="optiongroup checkboxgroup">
              <label class="checkboxlabel">
                <input type="checkbox" id="rawmode"> Nyers mód (professzionális)
              </label>
            </div>

            <div class="optiongroup">
              <label for="seed" class="textbutton">Seed (reprodukálhatóság):</label>
              <input type="number" id="seed" placeholder="Véletlenszerű" min="0" max="4294967295" class="textbutton">
            </div>

            <div class="optiongroup">
              <label for="promptupsampling" class="textbutton">Prompt fejlesztés:</label>
              <select id="promptupsampling" class="textbutton">
                <option value="true" selected>Igen (ajánlott)</option>
                <option value="false">Nem</option>
              </select>
            </div>
          </div>

          <button id="generatebutton" class="textbutton">Kép generálása</button>
          <div id="imageresult"></div>
        </div>
      </div>
    </div>
  </div>

  <script>
    document.addEventListener('DOMContentLoaded', () => {
      const searchInput = document.getElementById('searchinput');
      const searchButton = document.getElementById('searchbutton');
      const resultsContainer = document.getElementById('searchresults');

      // Tab elements
      const searchTab = document.getElementById('searchtab');
      const imageTab = document.getElementById('imagetab');
      const searchContent = document.getElementById('searchcontent');
      const imageContent = document.getElementById('imagecontent');

      // Image generation elements
      const imagePrompt = document.getElementById('imageprompt');
      const generateButton = document.getElementById('generatebutton');
      const imageResult = document.getElementById('imageresult');

      // Tab switching
      searchTab.addEventListener('click', () => {
        searchTab.classList.add('active');
        imageTab.classList.remove('active');
        searchContent.classList.add('active');
        imageContent.classList.remove('active');
      });

      imageTab.addEventListener('click', () => {
        imageTab.classList.add('active');
        searchTab.classList.remove('active');
        imageContent.classList.add('active');
        searchContent.classList.remove('active');
      });

      searchButton.addEventListener('click', performSearch);
      searchInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') performSearch();
      });

      generateButton.addEventListener('click', generateImage);

      async function generateImage() {
        const prompt = imagePrompt.value.trim();
        if (!prompt) return;

        // Get all the advanced options
        const aspectRatio = document.getElementById('aspectratio').value;
        const outputFormat = document.getElementById('outputformat').value;
        const outputQuality = parseInt(document.getElementById('outputquality').value);
        const safetyTolerance = parseInt(document.getElementById('safetytolerance').value);
        const rawMode = document.getElementById('rawmode').checked;
        const seed = document.getElementById('seed').value;
        const promptUpsampling = document.getElementById('promptupsampling').value === 'true';

        // Show loading in image result area
        imageResult.innerHTML = '<p class="textb2">Kép generálása...</p>';

        try {
          const requestBody = {
            prompt,
            aspect_ratio: aspectRatio,
            output_format: outputFormat,
            output_quality: outputQuality,
            safety_tolerance: safetyTolerance,
            raw: rawMode,
            prompt_upsampling: promptUpsampling
          };

          // Add seed if provided
          if (seed && !isNaN(parseInt(seed))) {
            requestBody.seed = parseInt(seed);
          }

          const response = await fetch('/generateimage', {
            method: 'POST',
            headers: {
              'ContentType': 'application/json'
            },
            body: JSON.stringify(requestBody)
          });

          const data = await response.json();

          if (data.imageUrl) {
            const seedInfo = data.seed ?  | Seed: ${data.seed} : '';
            imageResult.innerHTML = 
              <div class="generatedimage">
                <img src="${data.imageUrl}" alt="Generált kép" />
                <p class="textb2">Prompt: "${prompt}"</p>
                <p class="textb2">Beállítások: ${aspectRatio} | ${outputFormat.toUpperCase()} | Minőség: ${outputQuality}${seedInfo}</p>
              </div>
            ;
          } else {
            imageResult.innerHTML = '<p class="textb2">Nem sikerült generálni a képet.</p>';
          }
        } catch (error) {
          console.error('Error:', error);
          imageResult.innerHTML = '<p class="textb2">Hiba történt a képgenerálás közben.</p>';
        }
      }

      async function performSearch() {
        const query = searchInput.value.trim();
        if (!query) return;

        const searchType = document.getElementById('searchtype').value;
        const searchCategory = document.getElementById('searchcategory').value;
        const includeHighlights = document.getElementById('includehighlights').checked;
        const includeSummary = document.getElementById('includesummary').checked;
        const includeContent = document.getElementById('includecontent').checked;

        resultsContainer.innerHTML = '<p class="textb2">Keresés...</p>';

        try {
          let endpoint = '/search';
          let requestBody = { 
            query, 
            filters: { type: searchType }
          };

          // Use categoryspecific search if category is selected
          if (searchCategory) {
            endpoint = '/searchcategory';
            requestBody = { query, category: searchCategory };
          } else if (includeHighlights || includeSummary || includeContent) {
            // Use enhanced search for advanced features
            endpoint = '/searchenhanced';
            requestBody = {
              query,
              filters: { 
                type: searchType,
                text: true  // Always request text for enhanced features
              },
              highlights: includeHighlights,
              summary: includeSummary
            };
          }

          const response = await fetch(endpoint, {
            method: 'POST',
            headers: {
              'ContentType': 'application/json'
            },
            body: JSON.stringify(requestBody)
          });

          const data = await response.json();

          console.log('Search response data:', data);
          if (data.results && data.results.length > 0) {
            displayResults(data.results, includeContent);
          } else {
            resultsContainer.innerHTML = '<p class="textb2">Nem találhatók eredmények.</p>';
          }
        } catch (error) {
          console.error('Error:', error);
          resultsContainer.innerHTML = '<p class="textb2">Hiba történt a keresés közben.</p>';
        }
      }

      function displayResults(results, showContent = false) {
        console.log('Displaying results:', results);
        console.log('Show content:', showContent);
        resultsContainer.innerHTML = '';

        results.forEach((result, index) => {
          console.log(Result ${index}:, result);
          const resultItem = document.createElement('div');
          resultItem.className = 'resultitem';

          const title = document.createElement('h3');
          title.className = 'resulttitle';

          const link = document.createElement('a');
          link.href = result.url;
          link.textContent = result.title;
          link.target = '_blank';
          link.className = 'textmh4';

          title.appendChild(link);

          const url = document.createElement('p');
          url.className = 'resulturl textb2';
          url.textContent = result.url;

          resultItem.appendChild(title);
          resultItem.appendChild(url);

          // Add summary if available
          if (result.summary) {
            const summary = document.createElement('div');
            summary.className = 'resultsummary textb2';
            summary.innerHTML = <strong>Összefoglaló:</strong> ${result.summary};
            resultItem.appendChild(summary);
            console.log('Added summary:', result.summary);
          } else {
            console.log('No summary for result:', result.title);
          }

          // Add full text content if available and requested
          if (result.text && showContent) {
            const content = document.createElement('div');
            content.className = 'resultcontent textb2';
            content.innerHTML = <strong>Teljes tartalom:</strong><br>${result.text.substring(0, 1000)}${result.text.length > 1000 ? '...' : ''};
            resultItem.appendChild(content);
          }

          // Add highlights if available
          if (result.highlights && result.highlights.length > 0) {
            const highlightsDiv = document.createElement('div');
            highlightsDiv.className = 'resulthighlights';

            const highlightsTitle = document.createElement('h4');
            highlightsTitle.textContent = 'Kiemelések:';
            highlightsTitle.className = 'textbutton';
            highlightsDiv.appendChild(highlightsTitle);

            result.highlights.forEach(highlight => {
              const highlightItem = document.createElement('div');
              highlightItem.className = 'highlightitem textb2';
              highlightItem.innerHTML = highlight;
              highlightsDiv.appendChild(highlightItem);
            });

            resultItem.appendChild(highlightsDiv);
          }

          // Add action buttons
          const actionsDiv = document.createElement('div');
          actionsDiv.className = 'resultactions';

          const similarBtn = document.createElement('button');
          similarBtn.className = 'actionbtn textbutton';
          similarBtn.textContent = 'Hasonló cikkek';
          similarBtn.onclick = () => findSimilar(result.url);

          const contentBtn = document.createElement('button');
          contentBtn.className = 'actionbtn textbutton';
          contentBtn.textContent = 'Tartalom letöltése';
          contentBtn.onclick = () => getContent(result.id);

          actionsDiv.appendChild(similarBtn);
          actionsDiv.appendChild(contentBtn);
          resultItem.appendChild(actionsDiv);

          resultsContainer.appendChild(resultItem);
        });
      }

      async function findSimilar(url) {
        resultsContainer.innerHTML = '<p class="textb2">Hasonló cikkek keresése...</p>';

        try {
          const response = await fetch('/similar', {
            method: 'POST',
            headers: {
              'ContentType': 'application/json'
            },
            body: JSON.stringify({ url })
          });

          const data = await response.json();

          if (data.results && data.results.length > 0) {
            displayResults(data.results);
          } else {
            resultsContainer.innerHTML = '<p class="textb2">Nem találhatók hasonló cikkek.</p>';
          }
        } catch (error) {
          console.error('Error:', error);
          resultsContainer.innerHTML = '<p class="textb2">Hiba történt a hasonló cikkek keresése közben.</p>';
        }
      }

      async function getContent(id) {
        if (!id) {
          alert('Nincs elérhető tartalom ID');
          return;
        }

        try {
          const response = await fetch('/contents', {
            method: 'POST',
            headers: {
              'ContentType': 'application/json'
            },
            body: JSON.stringify({ ids: [id] })
          });

          const data = await response.json();

          if (data.results && data.results.length > 0) {
            const content = data.results[0];

            // Create a modal or new section to display content
            const modal = document.createElement('div');
            modal.style.cssText = 
              position: fixed;
              top: 0;
              left: 0;
              width: 100%;
              height: 100%;
              background: rgba(0, 0, 0, 0.9);
              zindex: 1000;
              display: flex;
              justifycontent: center;
              alignitems: center;
              padding: 20px;
            ;

            const modalContent = document.createElement('div');
            modalContent.style.cssText = 
              background: rgba(255, 255, 255, 0.08);
              borderradius: 16px;
              padding: 32px;
              maxwidth: 800px;
              maxheight: 80%;
              overflowy: auto;
              border: 1px solid rgba(255, 255, 255, 0.2);
            ;

            modalContent.innerHTML = 
              <h2 class="textmh2" style="color: white; marginbottom: 20px;">${content.title}</h2>
              <p class="textb2" style="color: rgba(255,255,255,0.7); marginbottom: 20px;">${content.url}</p>
              <div class="textb2" style="color: rgba(255,255,255,0.9); lineheight: 1.6;">${content.text || 'Nincs elérhető tartalom'}</div>
              <button onclick="this.parentElement.parentElement.remove()" class="textbutton" style="margintop: 20px; padding: 10px 20px; background: rgba(255,255,255,0.15); border: 1px solid rgba(255,255,255,0.3); borderradius: 8px; color: white; cursor: pointer;">Bezárás</button>
            ;

            modal.appendChild(modalContent);
            document.body.appendChild(modal);

            modal.onclick = (e) => {
              if (e.target === modal) {
                modal.remove();
              }
            };
          } else {
            alert('Nem sikerült letölteni a tartalmat');
          }
        } catch (error) {
          console.error('Error:', error);
          alert('Hiba történt a tartalom letöltése közben');
        }
      }
    });
  </script>
</body>
</html>


js: // Simple functionality only
document.addEventListener('DOMContentLoaded', function() {
  const searchTab = document.getElementById('searchtab');
  const imageTab = document.getElementById('imagetab');
  const searchContent = document.getElementById('searchcontent');
  const imageContent = document.getElementById('imagecontent');

  searchTab.addEventListener('click', () => {
    searchTab.classList.add('active');
    imageTab.classList.remove('active');
    searchContent.classList.add('active');
    imageContent.classList.remove('active');
  });

  imageTab.addEventListener('click', () => {
    imageTab.classList.add('active');
    searchTab.classList.remove('active');
    imageContent.classList.add('active');
    searchContent.classList.remove('active');
  });

  const searchButton = document.getElementById('searchbutton');
  const searchInput = document.getElementById('searchinput');
  const resultsContainer = document.getElementById('searchresults');

  searchButton.addEventListener('click', performSearch);
  searchInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') performSearch();
  });

  async function performSearch() {
    const query = searchInput.value.trim();
    if (!query) return;

    try {
      searchButton.textContent = 'Keresés...';
      searchButton.disabled = true;

      const response = await fetch('/search', {
        method: 'POST',
        headers: {
          'ContentType': 'application/json'
        },
        body: JSON.stringify({ query })
      });

      const data = await response.json();
      displayResults(data.results);
    } catch (error) {
      console.error('Keresési hiba:', error);
      resultsContainer.innerHTML = '<p>Keresési hiba történt</p>';
    } finally {
      searchButton.textContent = 'Keresés';
      searchButton.disabled = false;
    }
  }

  function displayResults(results) {
    if (!results || results.length === 0) {
      resultsContainer.innerHTML = '<p>Nincs találat</p>';
      return;
    }

    const resultsHtml = results.map(result => 
      <div class="resultitem">
        <h3><a href="${result.url}" target="_blank">${result.title}</a></h3>
        <p class="resulturl">${result.url}</p>
      </div>
    ).join('');

    resultsContainer.innerHTML = resultsHtml;
  }

  const generateButton = document.getElementById('generatebutton');
  const imagePrompt = document.getElementById('imageprompt');
  const imageResult = document.getElementById('imageresult');

  if (generateButton) {
    generateButton.addEventListener('click', generateImage);
  }

  async function generateImage() {
    const prompt = imagePrompt.value.trim();
    if (!prompt) return;

    try {
      generateButton.textContent = 'Generálás...';
      generateButton.disabled = true;

      const response = await fetch('/generateimage', {
        method: 'POST',
        headers: {
          'ContentType': 'application/json'
        },
        body: JSON.stringify({ prompt })
      });

      const data = await response.json();

      if (data.imageUrl) {
        imageResult.innerHTML = <img src="${data.imageUrl}" alt="Generált kép" style="max-width: 100%; height: auto; border-radius: 6px;">;
      } else {
        imageResult.innerHTML = '<p>Képgenerálás sikertelen</p>';
      }
    } catch (error) {
      console.error('Képgenerálási hiba:', error);
      imageResult.innerHTML = '<p>Képgenerálási hiba történt</p>';
    } finally {
      generateButton.textContent = 'Kép generálása';
      generateButton.disabled = false;
    }
  }

  function checkAuthStatus() {
    fetch('/.replit/auth/userinfo')
      .then(response => {
        if (response.ok) {
          return response.json();
        } else {
          throw new Error('Not authenticated');
        }
      })
      .then(data => {
        console.log('Authenticated as:', data);
      })
      .catch(error => {
        console.error('Authentication check failed:', error);
      });
  }
});


